// Vendored OpenSpec skills: generated by scripts/sync-vendor.mjs, never
// edited by hand. Discovers the skill set from the directory instead of a
// hardcoded list, so upstream adds a workflow and a sync PR teaches the
// plugin about it without a code change.

import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

export const VENDOR_ROOT = "vendor/openspec";
export const VENDOR_MANIFEST = "manifest.json";

export interface VendorManifest {
  readonly package: string;
  readonly version: string;
  readonly generatedBy: string;
  readonly skills: readonly string[];
}

export function loadVendorManifest(vendorDir: string): VendorManifest {
  const raw = readFileSync(join(vendorDir, VENDOR_MANIFEST), "utf-8");
  const value = JSON.parse(raw) as unknown;
  if (!value || typeof value !== "object") {
    throw new Error("vendor manifest: expected a JSON object");
  }
  const v = value as Record<string, unknown>;
  for (const key of ["package", "version", "generatedBy"] as const) {
    if (typeof v[key] !== "string") {
      throw new Error(`vendor manifest: missing string '${key}'`);
    }
  }
  if (!Array.isArray(v.skills) || v.skills.some((s) => typeof s !== "string")) {
    throw new Error("vendor manifest: 'skills' must be an array of strings");
  }
  return v as unknown as VendorManifest;
}

// Skill ids present on disk: every `skills/<id>/SKILL.md` under vendorDir.
// Sorted for deterministic registration order.
export function listVendoredSkillIds(vendorDir: string): string[] {
  const skillsRoot = join(vendorDir, "skills");
  return readdirSync(skillsRoot, { withFileTypes: true })
    .filter(
      (entry) =>
        entry.isDirectory() &&
        readFileSyncOrNull(join(skillsRoot, entry.name, "SKILL.md")) !== null,
    )
    .map((entry) => entry.name)
    .sort();
}

function readFileSyncOrNull(file: string): string | null {
  try {
    return readFileSync(file, "utf-8");
  } catch {
    return null;
  }
}
